pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 count) public {
        // Bound count to avoid test timeout and ensure feasible execution
        count = bound(count, 0, 200);
        // Record how many successful receives are performed
        uint256 successfulCalls = 0;
        for (uint256 i = 0; i < count; i++) {
            // Use a fresh address each time to simulate different actors, each with 1 wei
            address caller = address(uint160(uint256(keccak256(abi.encode(i, msg.sender, block.timestamp)))));
            vm.deal(caller, 1);
            vm.prank(caller);
            try c.receive{value: 1}() {
                successfulCalls++;
            } catch {
                // receive() in the reference never reverts; if it does, the call is not counted
            }
        }
        // General rule: after any sequence of receives, depositsCount must not be less than successfulCalls.
        // Overflow in buggy version can make depositsCount < successfulCalls (e.g., wraps to 0).
        assertTrue(c.depositsCount() >= successfulCalls);
    }
}

