pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 gasLimit) public {
        // Restrict gas to a reasonable range to trigger out-of-gas in receive.
        bound(gasLimit, 21000, 100000);

        // Record the deposits count before the call.
        uint256 depositsBefore = c.depositsCount();

        // Give some ether to the test contract for funding the call.
        vm.deal(address(this), amount);

        // Attempt a low-level call to the receive function with a limited gas budget.
        // receive() does not exist as a named external function, so we use a raw call.
        (bool success, ) = address(c).call{value: amount, gas: gasLimit}("");

        // depositsCount after the attempt.
        uint256 depositsAfter = c.depositsCount();

        // If the call failed, depositsCount must remain the same.
        // Buggy version increments depositsCount unconditionally even if the call reverts.
        assertTrue(success || depositsAfter == depositsBefore);
    }
}

