pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount <= address(c).balance + amount);
        // Pre-fund the contract via selfdestruct to create a state where ETH balance > 0 but depositsCount == 0
        // This is the scenario that the buggy contract cannot prevent but the reference handles correctly
        address funder = address(new Helper());
        vm.deal(funder, amount);
        vm.prank(funder);
        selfdestruct(payable(address(c)));
        // Now c has ETH balance = amount, depositsCount = 0
        // The rule: if c's ETH balance is > 0, then depositsCount must be > 0
        // The reference maintains this because every ETH ingress must go through receive which increments depositsCount
        // The buggy receive reverts, so selfdestruct can inject ETH without incrementing depositsCount, breaking the rule
        assertTrue(address(c).balance == 0 || c.depositsCount() > 0);
    }
}

contract Helper {
    // This helper exists solely to force-feed ETH to the contract under test via selfdestruct
    function destruct(address payable target) public {
        selfdestruct(target);
    }
}

